import numpy as np
from scipy.optimize import minimize
import itertools

def get_min_diff(x):
    s = x
    min_diff = float('inf')
    for p in itertools.permutations(s, 4):
        diff = abs(p[0]/p[3] - p[2]/p[1])
        if diff < min_diff:
            min_diff = diff
    return min_diff

def objective(x):
    return -get_min_diff(x)

best_val = 0
for _ in range(50):
    x0 = np.random.uniform(1, 100, 5)
    res = minimize(objective, x0, bounds=[(0.1, 1000)]*5, method='Nelder-Mead')
    if -res.fun > best_val:
        best_val = -res.fun

print(f"Maximized min_diff: {best_val}")

